using Microsoft.EntityFrameworkCore;
using RaceDay.Api.Models;
namespace RaceDay.Api.Data;
public sealed class RaceDayContext(DbContextOptions<RaceDayContext> options) : DbContext(options) {
 public DbSet<Role> Roles => Set<Role>(); public DbSet<User> Users => Set<User>(); public DbSet<Event> Events => Set<Event>(); public DbSet<Category> Categories => Set<Category>(); public DbSet<Enrolment> Enrolments => Set<Enrolment>(); public DbSet<Result> Results => Set<Result>();
 protected override void OnModelCreating(ModelBuilder b) {
  b.Entity<Role>().ToTable("Roles").HasKey(x=>x.RoleId); b.Entity<Role>().Property(x=>x.RoleName).HasColumnType("varchar(20)").IsRequired(); b.Entity<Role>().HasIndex(x=>x.RoleName).IsUnique();
  b.Entity<User>().ToTable("Users").HasKey(x=>x.UserId); b.Entity<User>().Property(x=>x.FullName).HasColumnType("varchar(100)").IsRequired(); b.Entity<User>().Property(x=>x.Email).HasColumnType("varchar(150)").IsRequired(); b.Entity<User>().HasIndex(x=>x.Email).IsUnique(); b.Entity<User>().Property(x=>x.PasswordHash).HasColumnType("varchar(255)").IsRequired(); b.Entity<User>().Property(x=>x.CreatedAt).HasColumnType("datetime").HasDefaultValueSql("GETDATE()"); b.Entity<User>().HasOne(x=>x.Role).WithMany(x=>x.Users).HasForeignKey(x=>x.RoleId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Event>().ToTable("Events", table => { table.HasCheckConstraint("CK_Events_EventType", "[EventType] IN ('Run', 'Walk', 'Cycle')"); table.HasCheckConstraint("CK_Events_EventDistanceKm", "[EventDistanceKm] > 0"); }).HasKey(x=>x.EventId); b.Entity<Event>().Property(x=>x.EventName).HasColumnType("varchar(150)").IsRequired(); b.Entity<Event>().Property(x=>x.Description).HasColumnType("varchar(1000)"); b.Entity<Event>().Property(x=>x.EventDate).HasColumnType("datetime").IsRequired(); b.Entity<Event>().Property(x=>x.Location).HasColumnType("varchar(200)").IsRequired(); b.Entity<Event>().Property(x=>x.RouteInfo).HasColumnType("varchar(500)"); b.Entity<Event>().Property(x=>x.EventDistanceKm).HasColumnType("decimal(6,2)").IsRequired(); b.Entity<Event>().Property(x=>x.EventType).HasColumnType("varchar(10)").IsRequired(); b.Entity<Event>().Property(x=>x.CreatedAt).HasColumnType("datetime").HasDefaultValueSql("GETDATE()"); b.Entity<Event>().HasOne(x=>x.Organiser).WithMany(x=>x.Events).HasForeignKey(x=>x.OrganiserId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Category>().ToTable("Categories", table => { table.HasCheckConstraint("CK_Categories_DistanceKm", "[DistanceKm] > 0"); table.HasCheckConstraint("CK_Categories_MaxParticipants", "[MaxParticipants] > 0"); }).HasKey(x=>x.CategoryId); b.Entity<Category>().Property(x=>x.CategoryName).HasColumnType("varchar(50)").IsRequired(); b.Entity<Category>().Property(x=>x.DistanceKm).HasColumnType("decimal(5,2)").IsRequired(); b.Entity<Category>().Property(x=>x.MaxParticipants).HasDefaultValue(100); b.Entity<Category>().HasOne(x=>x.Event).WithMany(x=>x.Categories).HasForeignKey(x=>x.EventId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Enrolment>().ToTable("Enrolments").HasKey(x=>x.EnrolmentId); b.Entity<Enrolment>().Property(x=>x.EnrolmentDate).HasColumnType("datetime").HasDefaultValueSql("GETDATE()"); b.Entity<Enrolment>().Property(x=>x.Status).HasColumnType("varchar(20)").HasDefaultValue("Registered").IsRequired(); b.Entity<Enrolment>().HasIndex(x=>new{x.ParticipantId,x.CategoryId}).IsUnique(); b.Entity<Enrolment>().HasOne(x=>x.Participant).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.ParticipantId).OnDelete(DeleteBehavior.Restrict); b.Entity<Enrolment>().HasOne(x=>x.Category).WithMany(x=>x.Enrolments).HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.Restrict);
  b.Entity<Result>().ToTable("Results", table => { table.HasCheckConstraint("CK_Results_Position", "[Position] IS NULL OR [Position] > 0"); table.HasCheckConstraint("CK_Results_FinishTime", "[FinishTime] > '00:00:00'"); }).HasKey(x=>x.ResultId); b.Entity<Result>().Property(x=>x.FinishTime).HasColumnType("time").IsRequired(); b.Entity<Result>().Property(x=>x.RecordedAt).HasColumnType("datetime").HasDefaultValueSql("GETDATE()"); b.Entity<Result>().HasIndex(x=>x.EnrolmentId).IsUnique(); b.Entity<Result>().HasOne(x=>x.Enrolment).WithOne(x=>x.Result).HasForeignKey<Result>(x=>x.EnrolmentId).OnDelete(DeleteBehavior.Restrict); b.Entity<Result>().HasOne(x=>x.RecordedBy).WithMany().HasForeignKey(x=>x.RecordedByUserId).OnDelete(DeleteBehavior.Restrict);
 }
}
